def load() -> pd.DataFrame:
    import pandas as pd, glob
    paths = [
      'data/environment/input/tenean_beach_datasheet.csv',
      'data/environment/input/wollaston_beach_datasheet.csv',
      'data/environment/input/malibu_beach_datasheet.csv',
      'data/environment/input/m_street_beach_datasheet.csv',
      'data/environment/input/pleasure_bay_and_castle_island_beach_datasheet.csv',
      'data/environment/input/constitution_beach_datasheet.csv',
      'data/environment/input/city_point_beach_datasheet.csv',
      'data/environment/input/carson_beach_datasheet.csv',
    ]
    rows = []
    for p in paths:
        for fp in glob.glob(p):
            try:
                df = pd.read_csv(fp)
            except Exception:
                df = pd.read_csv(fp, engine='python')
            samp = pd.concat([df.head(3), df.tail(3)], ignore_index=True)
            samp['__file__'] = fp
            rows.append(samp)
    return pd.concat(rows, ignore_index=True)

def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/environment/input/boston-harbor-beaches.txt'
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        content = f.read()
    return pd.DataFrame([{'file': path, 'content': content}])
